import json
import re

with open('/root/DATA/products/CoachForce.json', 'r') as f:
    data = json.load(f)

# Track findings
results = {
    "slack_messages": [],
    "documents": [],
    "meeting_transcripts": [],
    "all_eids": set()
}

# Search in slack messages
if 'slack' in data:
    for item in data['slack']:
        if isinstance(item, dict) and 'Message' in item:
            text = item['Message'].get('User', {}).get('text', '')
            if 'Market Research Report' in text:
                user_id = item['Message'].get('User', {}).get('userId', '')
                results["slack_messages"].append({
                    "userId": user_id,
                    "timestamp": item['Message'].get('User', {}).get('timestamp', ''),
                    "text": text[:200] + "..." if len(text) > 200 else text
                })
                results["all_eids"].add(user_id)

# Search in documents
if 'documents' in data:
    for doc in data['documents']:
        if doc.get('type') == 'Market Research Report':
            author = doc.get('author', '')
            results["documents"].append({
                "id": doc.get('id', ''),
                "author": author,
                "date": doc.get('date', ''),
                "feedback": doc.get('feedback', '')[:200] if doc.get('feedback') else ''
            })
            results["all_eids"].add(author)

# Search in meeting transcripts
if 'meeting_transcripts' in data:
    for meeting in data['meeting_transcripts']:
        if meeting.get('document_type') == 'Market Research Report':
            # Extract employee IDs from participants
            participants = meeting.get('participants', [])
            for p in participants:
                results["all_eids"].add(p)
            results["meeting_transcripts"].append({
                "id": meeting.get('id', ''),
                "date": meeting.get('date', ''),
                "participants": participants
            })

            # Extract any eids from the transcript text
            transcript = meeting.get('transcript', '')
            eids_in_transcript = re.findall(r'eid_[a-f0-9]{8}', transcript)
            for eid in eids_in_transcript:
                results["all_eids"].add(eid)

# Print results
print("=== SLACK MESSAGES MENTIONING 'MARKET RESEARCH REPORT' ===")
for msg in results["slack_messages"]:
    print(f"User ID: {msg['userId']}")
    print(f"Timestamp: {msg['timestamp']}")
    print(f"Text: {msg['text']}\n")

print("\n=== DOCUMENTS OF TYPE 'MARKET RESEARCH REPORT' ===")
for doc in results["documents"]:
    print(f"Document ID: {doc['id']}")
    print(f"Author: {doc['author']}")
    print(f"Date: {doc['date']}")
    if doc['feedback']:
        print(f"Feedback: {doc['feedback']}")
    print()

print("\n=== MEETING TRANSCRIPTS FOR 'MARKET RESEARCH REPORT' ===")
for meeting in results["meeting_transcripts"]:
    print(f"Meeting ID: {meeting['id']}")
    print(f"Date: {meeting['date']}")
    print(f"Participants: {meeting['participants']}")
    print()

print("\n=== ALL UNIQUE EMPLOYEE IDs FOUND ===")
for eid in sorted(results["all_eids"]):
    print(eid)

EOF
